   });
   ```

6. In the `index.ts` file, import and start the server using the following code:

   ```typescript
   import { resolve } from 'path';
   import { fileURLToPath } from 'url';
   import { App } from './app';

   const __dirname = resolve(fileURLToPath(import.meta.url), '..');

   const main = async () => {
     try {
       await App.init(__dirname);
     } catch (err) {
       console.error(err);
     }
   };

   void main();
   ```

   This code loads the `App` class from the `app.ts` file and starts it by calling its `init()` method. The `__dirname` constant provides the path to the root directory of your project.

7. Finally, create the `App` class in `app.ts`:

   ```typescript
   import express, { Application } from 'express';
   import { Container } from 'typedi';

   export class App {
     public app: Application;

     public init(basePath: string): Promise<void> {
       this.app = express();
       this.config();
       this.routes();
       this.connection();

       return Promise.resolve();
     }

     private config(): void {
       const accessControl = require('./middleware/access-control');
       const logger = require('./middleware/logger');

       this.app.use(accessControl);
       this.app.use(logger);
     }

     private routes(): void {
