        const options = context.options[RULE_NAME] || {};

        // Check if the callback function in argument mutates state
        const callbackFn = node.arguments[0];
        const { body } = callbackFn;

        if (body.length === 0) return;

        let mutatesState = false;
        let callsMutatingMethod = false;

        // Check if callback function directly mutates state
        body.forEach((statement) => {
          if (
            VueAstUtils.isAssignmentExpression(statement) &&
            statement.left.object.type === 'ThisExpression'
          ) {
            mutatesState = true;

            // Check if callback function calls other methods that mutate state
            VueAstUtils.traverseUp(
              statement,
              (node) => {
                if (
                  VueAstUtils.isFunctionExpression(node) &&
                  node.id &&
                  VueAstUtils.isAssignmentExpression(node.body.statements[0]) &&
                  node.body.statements[0].left.object.type === 'ThisExpression'
                ) {
                  callsMutatingMethod = true;
                }
                return true;
              },
              {
                stopAtFunction: true,
              }
            );
          }
        });

        if (mutatesState || callsMutatingMethod) {
          const fix = (fixer) => {
            return fixer.replaceText(node, `{${options.handleMutations}}()`);
          };

          context.report({
            node,
            message: `Updated lifecycle hook ${callee.name} should not mutate internal component state.`,
            fix,
            data: { type: MUTATE_STATE },
          });
        }
      },
    };

    return {
      Visitor: context.createVisitor(visitor),
    };
  },
};
```

