const { RuleTester } = require('eslint');
const parserOptions = require('./parser-options');

const ruleTester = new RuleTester({
  parser: 'vue-eslint-parser',
  parserOptions: {
    ecmaVersion: 2021,
    sourceType: 'module',
    ...parserOptions
  },
  env: {
    es2021: true,
    node: true
  }
});

const mutatorCheck = (node, callStack) => {
  // List of mutating methods
  const mutatingMethods = [
    'push',
    'pop',
    'splice',
    'reverse',
    'sort',
    'shift',
    'unshift'
  ];

  // Check if node is of type "CallExpression" and if its "callee" property matches one of the mutating methods
  if (node.type === 'CallExpression' && mutatingMethods.includes(node.callee.name)) {
    // Add the calling method to the call stack
    callStack.push(node.callee.name);

    return true;
  }

  // Loop through the arguments of the CallExpression and recursively check if any argument is another CallExpression with a mutating method as its callee
  if (Array.isArray(node.arguments)) {
    return node.arguments.some(arg => mutatorCheck(arg, callStack));
  }

  return false;
};

const getCallStack = node => {
  const callStack = [];

  // Recursive function to traverse the parent chain of the CallExpression node
  function traverse(node) {
    if (node.type === 'CallExpression' && mutatorCheck(node, callStack)) {
      return;
    }

    if (Array.isArray(node.arguments)) {
      node.arguments.forEach(arg => traverse(arg));
    }

    if (node.parent && [ 'AssignmentExpression', 'ExpressionStatement' ].includes(node.parent.type)) {
      traverse(node.parent);
    }
  }

  traverse(node);

  return callStack;
};

ruleTester.run('vue/no-mutating-lifecycle-meths', {
  meta: {
    type: 'problem',
    docs: {
      description: 'Prohibit mutating lifecycle methods and methods called from them',
      recommended: true
    },
    fixable: 'inline',
    messages: {
      always: `Lifecycle hooks must not mutate internal component state. Found mutation in ${getCallStack(msg))}.`,
      avoidCall: `Avoid calling mutating methods from lifecycle hooks. Found mutation in ${getCallStack(msg)). Found calling method: ${msg.callingMethodName}.`
    }
  },
  create: (context) => {
    return {
      'CallExpression:exit'(node) {
        if (!context.getOptions().vueVersion || context.getOptions().vueVersion < 3) {
          return;
        }

        // Check if the node is a lifecycle method
        if (['beforeCreate', 'created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'beforeDestroy', 'destroyed'].includes(node.property.name)) {
          // Extract the CallExpressions within the method and check if they mutate internal state
          const callStack = [];

          if (mutatorCheck(node, callStack)) {
            const callingMethodName = callStack[callStack.length - 1];

            context.report({
              node,
              messageId: 'always',
              messageId: callStack.length > 1 ? 'avoidCall' : 'always',
              data: { msg: node, callingMethodName }
            });
          }
        }
      }
    };
  }
});

// Generate parser options based on the Vue.js version
function parserOptions() {
  const vueVersion = parseInt(process.env.npm_package_version.split('.')[0]);

  return {
    parser: { vueTemplate: true },
    ecmaVersion: vueVersion >= 3 ? 2021 : 2018,
    sourceType: 'module'
  };
}
