const { RuleTester, ESLintUtils } = require('eslint');
const { defaultTemplate, DEFAULT_TYPES_TO_EXCLUDE } = require('./rule-utils');

const { Linter } = require('eslint');

const rule = ESLintUtils.RuleBuilder.create('mutation-state-rule')
  .doc({
    description: 'Enforces not mutating internal component state within lifecycle hooks.',
    category: 'Vue',
    recommended: true,
    purpose:
      'This rule ensures that updated lifecycle hooks do not contain methods that modify the internal component state by calling methods that mutate internal state.',
  })
  .params({
    typesToExclude: {
      type: 'arrayOf',
      items: { type: 'string' },
      default: DEFAULT_TYPES_TO_EXCLUDE,
      description: 'List of Vue types (e.g. "props", "data", "computed") to exclude from the check.',
    },
  })
  .validate((ctx, { typesToExclude }) => {
    const linter = new Linter().defineRule({
      name: 'mutation-state-rule',
      defaultOptions: {
        typesToExclude,
      },
      meta: {
        docs: {
          description: 'Enforce not mutating internal component state within lifecycle hooks.',
        },
        fixable: 'code',
        schema: [],
        type: 'problem',
      },
      create(context) {
        const typesToExclude = new Set(typesToExclude);
        const restrictedMethods = new Set(['$forceUpdate', '$update']);

        return {
          'ExpressionStatement:exit'(node) {
            const { parent } = node;

            if (
              parent.type !== 'MethodBody' ||
              !parent.parent.parent.type.includes('LifecycleHook')
            ) {
              return;
            }

            const { callee } = node.expression;
            const { property } = callee;

            if (
              typesToExclude.has(property.value) ||
              restrictedMethods.has(callee.name)
            ) {
              return;
            }

            context.report({
              node,
              message:
                'Lifecycle hook contains a method that mutates internal component state: {{methodName}}.',
              fix(fixer) {
                return fixer.replaceText(node, defaultTemplate);
              },
              data: {
                methodName: property.value,
              },
            });

            const parentArg = getParentArgs(node);

            if (parentArg && parentArg.length > 0) {
              context.report({
                node: parentArg[0],
                message:
                  'Lifecycle hook calls a method that may mutate internal component state: {{methodName}}.',
                fix(fixer) {
                  return fixer.replaceText(parentArg[0], defaultTemplate);
                },
                data: {
                  methodName: property.value,
                },
              });
            }
          },
        };
      },
    });

    linter.verify(ctx.getFixtures(), {
      rules: {
        'mutation-state-rule': { typesToExclude },
      },
    });
  });

function getParentArgs(node) {
  const parent = node.parent;
  if (parent.type === 'ExpressionStatement') {
    return parent.expression.arguments;
  }

  return null;
}

module.exports = rule;
```

Here, we're using RuleBuilder from ESLint-Utils to create the rule, and are leveraging an extra `rule-utils` module to keep the code tidier.

The actual implementation of the rule works similarly to the RuleTester example, but we're now using a formal Linter API to verify files against the rules.

