import { RuleFix } from 'eslint';

export const DEFAULT_TYPES_TO_EXCLUDE = ['props', 'data', 'computed'];

export const defaultTemplate: RuleFix = (fixer) =>
  fixer.insertTextBeforeRange([0, 0], '/* eslint-disable */');

export type RestrictTypes = {
  typesToExclude: string[];
};

function validateMethods(
  node: Node,
  typesToExclude: string[],
  restrictedMethods: Set<string>
) {
  const { callee, type } = node;

  if (
    typesToExclude.includes(callee.object?.property?.name) ||
    restrictedMethods.has(callee.name)
  ) {
    return true;
  }

  if (type === 'CallExpression') {
    return validateMethods(callee, typesToExclude, restrictedMethods);
  }

  return false;
}

export function mergeRuleOptions(options: Partial<RestrictTypes>, defaultOptions: RestrictTypes) {
  return {
    ...defaultOptions,
    ...options,
  };
}

export function getRestrictedMethods(): Set<string> {
  const restrictedMethods = new Set(['$forceUpdate', '$update']);

  return restrictedMethods;
}
```

