       return node.object.name + "." + node.property.name;
     }

     if (node.type === "MemberExpression" && node.object.type === "ThisExpression") {
       return context.getParentNode(node, "Identifier").name + "." + node.property.name;
     }

     throw new Error(`Unexpected component property: ${JSON.stringify(node)}`);
   }

   function context.getParentNode(node, type) {
     let parent = node.parent;

     while (parent && parent.type !== type) {
       parent = parent.parent;
     }

     return parent;
   }
   ```

   This custom rule will enforce the following linting rule:

   - If any lifecycle hook method (in this example, `created`) modifies internal component state directly (`this` property), or calls a method that modifies internal component state (`props` or `data` properties), a warning will be emitted.

   - The rule also provides a fix for the linting issue, by extracting the `props` object from the method arguments and using a `const` statement to destructure and avoid mutating the props.

8. Add the following code to the `.eslintrc` file to extend the configuration:

   ```json
   {
     "extends": ["plugin:vue/most", "plugin:no-mutating-state"]
   }
   ```

   This enables your custom rule and add the "standard" extension.

9. Test your custom rule by creating a new file called `example.vue` and adding the following content:

   ```vue
   <template>
     <div>{{ message }}</div>
   </template>

   <script>
   import { ref } from "vue";

   export default {
     name: "ExampleComponent",
     setup() {
       const message = ref("Hello, world!");

       // Rule will report a violation
       created() {
         message.value = "Changed! ";
       }

       // Rule will report a violation
       created() {
         props.value = {};
       }

       // Rule will report a violation
       created() {
         data.value = { newProperty: "New value!" };
       }

       // Rule will not report a violation
       created() {
         const { message } = this;

         message.value = "Changed! ";

         this.someFunction({ foo: "bar" });
       }

       // Rule will not report a violation
       created() {
         const { props } = this;

         props.SomeProp = "Changed";

         this.otherFunction({ foo: "bar" });
       }

       // Rule will not report a violation
       created() {
         const { data } = this;

         data.newProperty = "New value!";

         this.anotherFunction({ foo: "bar" });
       }
     },
   };
   </script>
   ```

